// @mui material components
import Card from "@mui/material/Card";
import Icon from "@mui/material/Icon";
// Watch Selling App React components
import MDBox from "components/MDBox";
import MDTypography from "components/MDTypography";
import useAuth from "Firebase/Hooks/useAuth";
import { useEffect, useState } from "react";



function OrdersOverview() {
  const {isLoading, authError} = useAuth();
  const [allReviews, setReview] = useState([]);
  // console.log('hhh',allReviews)

  useEffect(() => {
      fetch('https://sleepy-journey-86126.herokuapp.com/review')
        .then((res) => res.json())
        .then((data) => setReview(data));
    }, [isLoading]);
  return (
    <Card sx={{ height: "100%" }}>
      <MDBox pt={3} px={3}>
        <MDTypography variant="h6" fontWeight="medium">
          Orders overview
        </MDTypography>
        <MDBox mt={0} mb={2}>
          <MDTypography variant="button" color="text" fontWeight="regular">
            <MDTypography display="inline" variant="body2" verticalAlign="middle">
              <Icon sx={{ color: ({ palette: { success } }) => success.main }}>arrow_upward</Icon>
            </MDTypography>
            &nbsp;
            <MDTypography variant="button" color="text" fontWeight="medium">
               {allReviews.length}
            </MDTypography>{" "}
            this month
          </MDTypography>
        </MDBox>
      </MDBox>
      <MDBox p={2}>
         { allReviews.map((riv,dx) =>(
            <div className="d-flex">
                  <img
                     src={riv.productUrl}
                     loading="lazy"
                     width="10%"
                   />
               <div className="ms-3">
                 <MDTypography variant="h6" fontWeight="medium">
                    {riv.productName}
                  </MDTypography>
                   <MDTypography variant="button" color="text" fontWeight="medium">
                     Rating : {riv.rating}
                   </MDTypography>
               </div>
           </div>))

         }
      </MDBox>
    </Card>
  );
}

export default OrdersOverview;
